<script setup lang="ts">
import { refreshFeedback as vRefreshFeedback } from '../../../shared/directives/refreshFeedback';
import { computed, defineAsyncComponent, nextTick, onUnmounted, ref, watch } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { Search, RefreshCw, Play, Pause, Database, ChevronLeft, ChevronRight } from '@lucide/vue';
import { discoveryAnalysisPrompt, type DiscoveryAnalysis } from '../discoveryAnalysis';
import DiscoveryExclusions from './DiscoveryExclusions.vue';
import SeedReviewWorkbench from './SeedReviewWorkbench.vue';
import ContinuousDiscovery from './ContinuousDiscovery.vue';
const AutonomousProbeWorkbench=defineAsyncComponent(()=>import('./AutonomousProbeWorkbench.vue'));
const enrichmentRevision=ref(0);
async function scopeConfirmed(){if(advanced.value){const g=generation;await refreshProgress(g,true);if(g!==generation||disposed)return;rootsText.value=data.value?.roots.join('\n')||'';}emit('confirmed');emit('changed');}
function enriched(){enrichmentRevision.value++;void refreshProgress(generation,true);queueLocal();emit('changed');}
import HunterExpansionProgress, { type HunterExpansion } from './HunterExpansionProgress.vue';
const props=defineProps<{projectId?:number;review?:DiscoveryAnalysis;batchReview?:boolean;archived?:boolean}>();const emit=defineEmits<{changed:[];confirmed:[];collect:[];results:[];analyze:[value:{analysis:DiscoveryAnalysis;prompt:string}]}>();
type Seed={id:number;host:string;source:string;reference:string;wildcard:boolean;eligible:boolean;queryEligible?:boolean;excluded?:boolean};
type Harvest={id:string;status:string;total:number;processed:number;skipped:number;added:number;certificates:number;reason:string;updatedAt:string};
type View={expansions?:HunterExpansion[];roots:string[];seeds:Seed[];seedTotal?:number;allSeeds?:number;seedPage?:number;seedPageSize?:number;harvest?:Harvest|null;settings:{keyConfigured:boolean;contractVerified:boolean;maxRequests:number;maxResults:number};requests?:{id:string;day:string;state:string;receipt:unknown}[];nextCursor?:number;batchRows?:number};
type LocalMatch={target:string;kind:string;matchCount:number;endpointMatches:number;certificateMatches:number;rawCertificateMatches:number;certificateCount:number;certificates:{fingerprint:string;domains:string[];assetIds:number[];eligible:boolean}[];assets:{id:number;host:string;matchType:string;certificatePresent:boolean}[];inspectionTruncated:boolean;certificatePreviewTruncated:boolean;harvest?:Harvest|null};
const advanced=ref(false),manualProbe=ref(false);
const data=ref<View>(),rootsText=ref(''),target=ref(''),hunterKind=ref('domain'),cursor=ref(0),busy=ref(false),reading=ref(false),error=ref(''),notice=ref(''),receipt=ref<unknown>();
type Admission={eligible:boolean;reason:string;anchor?:string};
const admission=ref<Admission>();
const seedSearch=ref(''),seedSource=ref('all'),seedPage=ref(1),localMatch=ref<LocalMatch>(),localLoading=ref(false),localError=ref('');
let generation=0,pageSequence=0,localSequence=0,disposed=false,pendingUntil=0;
let pollTimer:ReturnType<typeof setTimeout>|undefined,searchTimer:ReturnType<typeof setTimeout>|undefined,localTimer:ReturnType<typeof setTimeout>|undefined;
const harvesting=computed(()=>!!data.value?.harvest&&['running','stopping'].includes(data.value.harvest.status));
const harvestPercent=computed(()=>{const h=data.value?.harvest;return !h?0:h.status==='completed'?100:h.total?Math.min(100,Math.floor(h.processed/h.total*100)):0;});
const pageCount=computed(()=>Math.max(1,Math.ceil((data.value?.seedTotal??data.value?.seeds.length??0)/(data.value?.seedPageSize??50))));
const labels:Record<string,string>={running:'正在自动提取',stopping:'正在暂停',paused:'已暂停',interrupted:'已中断，可继续',failed:'提取遇到问题，可继续',completed:'本轮提取完成'};
const sources:Record<string,string>={observed_host:'已收录主机',certificate_name:'证书 CN / SAN',page:'已采集页面',certificate_domain:'证书域名',certificate_cn:'证书 CN',certificate_sha256:'证书 SHA-256',cname:'测绘 CNAME',page_or_inline_script:'页面 / 内联脚本',certificate_transparency:'证书透明度',dns_cname:'DNS CNAME',confirmed_scope:'已确认范围',confirmed_review_name:'全项目审阅确认的域名'};
const matchTypes:Record<string,string>={endpoint:'本地主机',certificate_exact:'证书域名精确匹配',certificate_wildcard:'通配证书覆盖，仅线索',fingerprint:'证书指纹匹配',saved_lead:'已保存的历史线索'};
function schedule(g=generation){clearTimeout(pollTimer);if(advanced.value&&!disposed&&g===generation&&(Date.now()<pendingUntil||harvesting.value||data.value?.expansions?.some(i=>['running','stopping'].includes(i.status))))pollTimer=setTimeout(()=>void refreshProgress(g),1500);}
async function readPage(g=generation){
 const projectId=props.projectId,seq=++pageSequence;if(!advanced.value||!projectId||disposed||g!==generation)return;
 reading.value=true;
 try{const v=await invoke<View>('get_asset_discovery_page',{projectId,search:seedSearch.value,source:seedSource.value,page:seedPage.value});if(disposed||g!==generation||seq!==pageSequence)return;
  const before=data.value?.harvest;data.value=v;seedPage.value=v.seedPage??seedPage.value;
  if(before&&before.status!=='completed'&&v.harvest?.id===before.id&&v.harvest.status==='completed'){notice.value=`本轮已处理 ${v.harvest.processed.toLocaleString()} 条资产，新增 ${v.harvest.added.toLocaleString()} 条线索。没有联网或消耗积分。`;emit('changed');queueLocal();}
 }catch(e){if(g===generation&&seq===pageSequence)error.value=String(e);}
 finally{if(g===generation&&seq===pageSequence)reading.value=false;}
}
async function refreshProgress(g=generation,force=false){if(force)pendingUntil=Date.now()+5000;await readPage(g);schedule(g);}
async function load(){const p=props.projectId,g=++generation;++localSequence;++pageSequence;clearTimeout(pollTimer);clearTimeout(searchTimer);clearTimeout(localTimer);data.value=undefined;error.value='';localMatch.value=undefined;admission.value=undefined;localError.value='';localLoading.value=false;cursor.value=0;rootsText.value='';target.value='';hunterKind.value='domain';receipt.value=undefined;notice.value='';seedSearch.value='';seedSource.value='all';seedPage.value=1;busy.value=false;reading.value=false;if(!p)return;busy.value=true;try{await readPage(g);if(disposed||g!==generation)return;const loaded=data.value as View|undefined;rootsText.value=loaded?.roots.join('\n')||'';target.value=loaded?.roots[0]||'';schedule(g);}finally{if(g===generation)busy.value=false;}}
async function changePage(page:number){if(reading.value)return;seedPage.value=Math.max(1,Math.min(pageCount.value,page));error.value='';await refreshProgress();}
function searchSeeds(){clearTimeout(searchTimer);seedPage.value=1;const g=generation;searchTimer=setTimeout(()=>void refreshProgress(g),300);}
function queueLocal(){clearTimeout(localTimer);++localSequence;localMatch.value=undefined;admission.value=undefined;localError.value='';localLoading.value=advanced.value&&!!target.value.trim()&&!!props.projectId;if(!localLoading.value)return;const g=generation;localTimer=setTimeout(()=>void checkLocal(g),400);}
async function checkLocal(g=generation){clearTimeout(localTimer);const projectId=props.projectId,value=target.value.trim(),seq=++localSequence;if(!advanced.value||!projectId||!value||disposed||g!==generation)return;localLoading.value=true;localError.value='';try{const [result,preview]=await Promise.all([invoke<LocalMatch>('lookup_local_discovery',{projectId,target:value}),invoke<Admission>('preview_hunter_evidence',{input:{projectId,target:value,kind:hunterKind.value}})]);if(disposed||g!==generation||seq!==localSequence)return;localMatch.value=result;admission.value=preview;}catch(e){if(g===generation&&seq===localSequence)localError.value=String(e);}finally{if(g===generation&&seq===localSequence)localLoading.value=false;}}
async function startHarvest(){const projectId=props.projectId,g=generation;if(!projectId||busy.value||harvesting.value)return;busy.value=true;error.value='';try{const h=await invoke<Harvest>('start_asset_discovery_harvest',{projectId});if(disposed||g!==generation)return;if(data.value)data.value.harvest=h;notice.value='本地提取已启动，后台会自动处理本轮全部资产，可随时暂停。';pendingUntil=Date.now()+5000;schedule(g);}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function pauseHarvest(){const projectId=props.projectId,id=data.value?.harvest?.id,g=generation;if(!projectId||!id||busy.value||!harvesting.value)return;busy.value=true;error.value='';try{const h=await invoke<Harvest>('pause_asset_discovery_harvest',{projectId,runId:id});if(disposed||g!==generation)return;if(data.value)data.value.harvest=h;schedule(g);}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function startHunter(){const projectId=props.projectId,g=generation;if(!projectId||busy.value||!target.value||!data.value?.settings.keyConfigured||!data.value.settings.contractVerified)return;busy.value=true;error.value='';notice.value='';try{const input={projectId,kind:hunterKind.value,target:target.value.trim()};const preview=await invoke<Admission>('preview_hunter_evidence',{input});if(disposed||g!==generation)return;admission.value=preview;if(!preview.eligible){error.value=preview.reason;return;}await invoke('start_hunter_expansion',{input});if(disposed||g!==generation)return;notice.value='已启动精确关联自动分页，可使用免费与权益积分，不设积分预算；每页保存回执，可随时暂停。';await refreshProgress(g,true);}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function act(action:string,h=target.value){if(action==='hunter'){await startHunter();return;}if(action==='harvest'){await startHarvest();return;}const p=props.projectId,g=generation;if(!p||busy.value)return;busy.value=true;error.value='';notice.value='';try{await invoke('act_asset_discovery',{input:{projectId:p,action,roots:rootsText.value.split(/[\s,;]+/).filter(Boolean),host:h,hunterKind:hunterKind.value,cursor:0,requestId:crypto.randomUUID()}});if(disposed||g!==generation)return;await readPage(g);if(disposed||g!==generation)return;if(action==='scopes'){rootsText.value=data.value?.roots.join('\n')||'';queueLocal();notice.value='当前项目的确认范围已保存。';}else notice.value=action==='promote'?'已加入下一次 FOFA 查询的域名种子，没有立即启动采集。':'线索已保存；发现来源不等于归属确认。';}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
const reviewPanel=ref<HTMLElement>();
const organization=ref(''),analysis=ref<DiscoveryAnalysis>(),analyzing=ref(false),selectedCandidates=ref<string[]>([]),confirmedRelationship=ref(false);
async function analyzeSeeds(){
 const projectId=props.projectId,g=generation;if(!projectId||analyzing.value||busy.value)return;
 analyzing.value=true;error.value='';
 try{const report=await invoke<DiscoveryAnalysis>('analyze_local_discovery',{projectId,organization:organization.value.trim()});if(disposed||g!==generation||projectId!==props.projectId)return;
 analysis.value=report;selectedCandidates.value=[];confirmedRelationship.value=false;emit('analyze',{analysis:report,prompt:discoveryAnalysisPrompt(report)});
 }catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)analyzing.value=false;}
}
async function confirmCandidates(){
 const report=analysis.value,projectId=props.projectId,g=generation;if(!report||report.projectId!==projectId||!confirmedRelationship.value||!selectedCandidates.value.length||busy.value)return;
 busy.value=true;error.value='';
 try{await invoke('confirm_local_discovery',{input:{projectId,organization:report.organization,hosts:[...selectedCandidates.value],expectedRoots:report.roots,userConfirmed:true}});if(disposed||g!==generation)return;
 await readPage(g);if(disposed||g!==generation)return;rootsText.value=data.value?.roots.join('\n')||'';analysis.value=undefined;selectedCandidates.value=[];confirmedRelationship.value=false;notice.value='已保存人工确认的域名范围；尚未启动采集、探测或 Hunter。';emit('confirmed');emit('changed');
 }catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}
}
function applyReview(){const report=props.review;if(report&&report.projectId===props.projectId){organization.value=report.organization;analysis.value=report;selectedCandidates.value=[];confirmedRelationship.value=false;void nextTick(()=>reviewPanel.value?.scrollIntoView?.({block:'start',behavior:'smooth'}));}}
async function openAdvanced(){if(advanced.value)return;advanced.value=true;await load();if(advanced.value&&!disposed)applyReview();}
function closeAdvanced(){advanced.value=false;manualProbe.value=false;++generation;++localSequence;++pageSequence;clearTimeout(pollTimer);clearTimeout(searchTimer);clearTimeout(localTimer);busy.value=false;reading.value=false;localLoading.value=false;}
watch(()=>props.review,report=>{if(report&&report.projectId===props.projectId){if(advanced.value)applyReview();else void openAdvanced();}});
watch(organization,value=>{if(analysis.value&&analysis.value.organization!==value.trim()){analysis.value=undefined;selectedCandidates.value=[];confirmedRelationship.value=false;}});
function localTime(value:string){const parsed=new Date(/Z$|[+-]\d\d:\d\d$/.test(value)?value:value.replace(' ','T')+'Z');return Number.isNaN(parsed.getTime())?value:parsed.toLocaleString('zh-CN',{hour12:false});}
function selectSeed(seed:Seed){target.value=seed.host;hunterKind.value=seed.source==='certificate_sha256'?'fingerprint':seed.source.includes('cname')?'cname':'domain';}
function useFingerprint(value:string){target.value=value;hunterKind.value='fingerprint';}
watch([target,hunterKind],queueLocal);
watch(()=>props.projectId,()=>{analysis.value=undefined;organization.value='';analyzing.value=false;selectedCandidates.value=[];confirmedRelationship.value=false;closeAdvanced();data.value=undefined;rootsText.value='';target.value='';if(props.review?.projectId===props.projectId)void openAdvanced();},{immediate:true});
onUnmounted(()=>{disposed=true;++generation;++localSequence;++pageSequence;clearTimeout(pollTimer);clearTimeout(searchTimer);clearTimeout(localTimer);});
</script>
<template>
<section class="discovery-workbench" :class="{panel:advanced}" data-testid="asset-discovery-workbench">
<p v-if="!projectId" class="discovery-empty">请先选择工作空间。</p>
<template v-else-if="!advanced">
<SeedReviewWorkbench :refresh-version="enrichmentRevision" :project-id="projectId" @collect="emit('collect')" @results="emit('results')" @confirmed="scopeConfirmed"/>
<div class="discovery-tools-entry"><button class="button ghost compact" data-discovery-action="collect" @click="emit('collect')">手动采集</button><button class="button ghost compact" data-discovery-action="advanced" @click="openAdvanced">高级工具</button></div>
</template>
<template v-else>
<header class="discovery-heading"><div><h3>高级发现工具</h3><p>手动管理范围、证书、CT / DNS 和 Hunter；常规发现由 AI 工作台自动推进。</p></div><div class="discovery-header-actions"><button class="button ghost compact" data-discovery-action="return" @click="closeAdvanced">返回 AI 发现</button><button v-refresh-feedback="{scope:projectId,busy:reading,error}" class="button ghost compact" :disabled="busy||reading" @click="refreshProgress(generation,true)"><RefreshCw :size="14"/>刷新</button></div></header>
<ContinuousDiscovery :project-id="projectId" :refresh-version="data?.roots?.join(',')" @changed="enriched"/>
<div class="manual-probe-entry"><button class="button ghost compact" data-discovery-action="manual-probe" @click="manualProbe=!manualProbe">{{manualProbe?'收起手动自主探测':'手动自主探测'}}</button></div>
<AutonomousProbeWorkbench v-if="manualProbe" :project-id="projectId" :archived="archived" @changed="enriched"/>
<details :open="!batchReview" class="discovery-legacy-analysis"><summary>在对话中讨论单次候选摘要（不代替全量 AI 审阅）</summary>
<section class="discovery-block seed-ai-entry"><h4>AI 提炼项目种子</h4><p class="helper">全量读取本地非回收资产，整理主机、证书和 CNAME 的观察摘要；转到对话草稿，由你发送给模型分析。归属和范围由你确认，确认前不会自动进入 Hunter。</p><div class="seed-ai-controls"><label class="field"><span>相关单位或域名关键词（可选，可填写多个）</span><input v-model="organization" maxlength="240" placeholder="例如：中国移动 中移，或 10086.cn" :disabled="analyzing||busy"/></label><button class="button primary" :disabled="analyzing||busy" data-discovery-action="analyze" @click="analyzeSeeds">{{analyzing?'正在全量整理本地摘要…':'AI 提炼 · 前往对话'}}</button></div><small class="muted">发送聊天时会将候选摘要交给当前模型；聊天授权沿用现有规则。</small></section></details>
<section v-if="analysis" ref="reviewPanel" class="discovery-block seed-review" data-testid="discovery-seed-review"><h4>核对候选并确认范围</h4><p>已遍历 {{analysis.scannedAssets.toLocaleString()}} 条本地资产；匹配 {{analysis.matchedAssets.toLocaleString()}} 条，发现 {{analysis.candidateTotal.toLocaleString()}} 个候选域名。{{analysis.previewTruncated?'仅展示前 80 项，可缩小单位或域名关键词重新分析。':''}}</p><p class="helper">以下是带本地来源的候选，不是 AI 已确认的资产。证书、CNAME、单位共现仍可能属于第三方；未勾选的域名不会加入范围。</p><div class="seed-review-list"><label v-for="candidate in analysis.candidates" :key="candidate.host"><input v-model="selectedCandidates" type="checkbox" :value="candidate.host" :disabled="busy||candidate.inConfirmedScope"/><span><strong>{{candidate.host}}</strong><small>{{candidate.inConfirmedScope?'已在确认范围 · ':''}}{{candidate.assetCount}} 条资产 · {{candidate.sources.map(source=>sources[source]||source).join(' / ')}} · #{{candidate.assetIds.join('、')}}</small><small>{{candidate.companies.join('、')||'没有单位归属证据'}}</small></span></label></div><label class="seed-confirm-relationship"><input v-model="confirmedRelationship" type="checkbox" :disabled="busy"/>我已核对，确认勾选的域名及其子域与目标单位相关，并允许加入后续探测范围。</label><button class="button primary compact" :disabled="busy||!confirmedRelationship||!selectedCandidates.length" @click="confirmCandidates">确认加入范围 · {{selectedCandidates.length}} 项</button><p class="helper">仅保存范围；没有启动 Hunter、探测或赋予正式资产归属。凭证、证书证据和共享目标准入仍单独校验。</p></section>
<div class="discovery-setup-grid">
<section class="discovery-block"><h4><span class="step-number">1</span>确认域名范围</h4><p class="helper">每行一个域名；共享平台请限定到你的具体租户。</p><label class="field"><span class="sr-label">明确确认的域名范围</span><textarea v-model="rootsText" rows="3" :disabled="busy" placeholder="example.com"/></label><footer><button class="button secondary compact" :disabled="busy" @click="act('scopes')">保存确认范围</button><span class="muted">已保存 {{data?.roots.length??0}} 个范围</span></footer></section>
<section class="discovery-block harvest-block"><h4><span class="step-number">2</span>自动整理本地线索</h4><p class="helper">整理本地观察记录，后台自动分批执行。提取数量不等于目标资产数，也不会自动送入 Hunter。</p><div v-if="data?.harvest" class="harvest-progress" role="status"><div><strong>{{labels[data.harvest.status]||data.harvest.status}}</strong><span>{{data.harvest.processed.toLocaleString()}} / {{data.harvest.total.toLocaleString()}} 条</span></div><progress :value="harvestPercent" max="100" :aria-label="`本地提取进度 ${harvestPercent}%`"/><p>新增 {{data.harvest.added.toLocaleString()}} 条线索 · 有证书字段 {{data.harvest.certificates.toLocaleString()}} 条资产（尚非证书准入数量）<span v-if="data.harvest.skipped"> · 已移除 / 不可读 {{data.harvest.skipped}} 条</span></p><small>{{data.harvest.reason}}</small><small class="harvest-updated">更新于 {{localTime(data.harvest.updatedAt)}} · 本轮资产快照，新入库资产可重新提取</small></div><div v-else class="harvest-empty"><Database :size="22"/><span>提取主机、证书、CNAME 和已采集页面中的域名</span></div><footer><button v-if="!harvesting" class="button primary compact" :disabled="busy" data-discovery-action="harvest" @click="startHarvest"><Play :size="14"/>{{data?.harvest&&data.harvest.status!=='completed'?'继续本地提取':data?.harvest?.status==='completed'?'重新提取全部资产':'一键提取全部资产'}}</button><button v-else class="button danger compact" :disabled="busy||data?.harvest?.status==='stopping'" data-discovery-action="pause-harvest" @click="pauseHarvest"><Pause :size="14"/>{{data?.harvest?.status==='stopping'?'正在暂停…':'暂停提取'}}</button><span class="local-only">仅整理本地 · 不查询 Hunter</span></footer></section>
</div>
<section class="discovery-block query-block"><h4><span class="step-number">3</span>先查本地，再精确补查</h4><div class="discovery-query-fields"><label class="field"><span>域名 / 证书 SHA-256 / CNAME 目标</span><input v-model="target" :disabled="busy" placeholder="输入域名，自动检查本地资产和证书" autocomplete="off"/></label><label class="field"><span>Hunter 补查依据</span><select v-model="hunterKind" :disabled="busy"><option value="domain">精确域名（仅此主机名）</option><option value="domain_tree">已确认域名树（根域和子域）</option><option value="fingerprint">证书 SHA-256 精确指纹</option><option value="cname">CNAME 精确目标</option></select></label></div>
<div v-if="target.trim()" class="local-match-panel" :aria-busy="localLoading"><p v-if="localLoading" role="status">正在核对本地记录，不会联网…</p><p v-else-if="localError" role="alert">{{localError}}</p><template v-else-if="localMatch"><div class="local-match-heading"><strong>{{localMatch.certificateMatches?(localMatch.certificateCount?'本地已有证书信息，可选择已保存指纹':'本地已有证书信息，缺少可用指纹'):localMatch.endpointMatches?'本地已有资产，尚未发现证书信息':localMatch.matchCount?'本地已有相关历史线索':'暂未发现本地匹配记录'}}</strong><span class="local-only">未发出外部请求</span></div><p>匹配 {{localMatch.matchCount}} 条本地资产 / 关联记录 · {{localMatch.certificateCount}} 个已保存指纹<span v-if="localMatch.inspectionTruncated">（仅预览前 200 条，不能据此排除后续记录）</span></p><p v-if="localMatch.harvest?.status!=='completed'" class="local-caution">{{harvesting?'本地全量提取正在进行，剩余证书线索会继续补充；完成后自动重新核对。':data?.harvest?'本地全量提取尚未完成，可继续本地提取后核对证书。':'本地全量提取尚未完成，IP 资产中的证书域名可能还未进入索引；可先点击“一键提取全部资产”。'}}</p><p v-if="localMatch.harvest?.status==='completed'&&!localMatch.matchCount" class="local-caution">最近一次提取更新于 {{localTime(localMatch.harvest.updatedAt)}}；若有新入库资产，可重新提取后再核对。</p><p v-if="localMatch.certificateMatches&&!localMatch.certificateCount" class="local-caution">已有证书内容或域名信息，但没有可用 SHA-256 指纹；不会用域名冒充指纹。</p><div v-if="localMatch.certificates.length" class="local-certificates"><article v-for="cert in localMatch.certificates" :key="cert.fingerprint"><div><span>SHA-256 · 本地资产 #{{cert.assetIds.slice(0,3).join('、')}}</span><code>{{cert.fingerprint}}</code><small v-if="cert.domains.length">{{cert.domains.slice(0,5).join('、')}}</small><small v-if="!cert.eligible" class="local-caution">需先完成本地提取，并确认该证书关联的域名范围。</small></div><button class="button secondary compact" :disabled="busy||!cert.eligible" @click="useFingerprint(cert.fingerprint)">使用此指纹</button></article><p v-if="localMatch.certificatePreviewTruncated">仅展示前 20 个不同指纹，请使用下方证书分类继续搜索。</p></div><details v-if="localMatch.assets.length"><summary>查看本地匹配依据</summary><ul><li v-for="asset in localMatch.assets" :key="asset.id"><span>#{{asset.id}} · {{asset.host}}</span><small>{{matchTypes[asset.matchType]||asset.matchType}}</small></li></ul></details><p class="local-match-note">本地存在记录不等于当前存活或归属已确认；通配证书覆盖也不表示该主机已发现。</p></template></div>
<div class="query-actions-group"><div><button class="button secondary compact" :disabled="busy||!target||hunterKind==='fingerprint'" @click="act('promote')">加入 FOFA 查询种子</button><button class="button ghost compact" :disabled="busy||!target||hunterKind==='fingerprint'" @click="act('ct')">CT 域名线索</button><button class="button ghost compact" :disabled="busy||!target||hunterKind==='fingerprint'" @click="act('dns')">DNS / CNAME</button></div><button class="button primary compact" :disabled="busy||localLoading||!target||!admission?.eligible||!data?.settings.keyConfigured||!data?.settings.contractVerified" @click="act('hunter')">{{data?.settings.contractVerified?'Hunter 精确关联 · 自动翻页':'Hunter 补查（接口待核实）'}}</button></div><p v-if="admission" class="helper" role="status">付费补查检查：{{admission.eligible?'已通过':'暂不允许'}} · {{admission.reason}}</p><p class="helper">域名补查须在确认范围内；证书补查还须核对同一张证书的指纹与域名。无关 / 混合范围证书、无域名依据的指纹及范围外共享 CNAME 不自动查询；证书匹配仍不等于归属确认。</p><p v-if="data&&!data.settings.contractVerified" class="helper">Hunter 实际查询暂未启用，不会发送付费请求。</p><p v-else-if="data&&!data.settings.keyConfigured" class="helper">请先在「配置中心 → 资产 API」保存并验证 Hunter API Key。</p><details class="query-explanation"><summary>查询范围、积分与数据使用说明</summary><p>CT 将本次域名提交给 crt.sh；DNS 使用 Google Public DNS。Hunter 核验线索来源后，遍历近 30 天的全部可用分页，去重合并并显示每页及累计积分消耗。可使用免费与权益积分，不设积分预算；平台限制、额度耗尽或结果未知时暂停，不自动重发。页面与脚本线索只从已采集数据提取，不执行脚本。发现来源不等于归属确认，同一张证书的 CN / SAN 用于本地核验，不会因此单独追加 Hunter 查询。同条件、同时间窗口复用查询记录；SHA-256 和 CNAME 属于不同查询，可能再次命中同一批资产。本地去重不代表平台退还重复结果的积分。</p></details></section>
<p v-if="busy" role="status" class="discovery-notice">正在处理，请勿重复点击…</p><p v-if="notice" role="status" class="discovery-notice">{{notice}}</p><p v-if="error" role="alert" class="form-error">{{error}}</p>
<HunterExpansionProgress :project-id="projectId" :items="data?.expansions" @changed="refreshProgress(generation,true)"/>
<section class="discovery-block seed-directory"><header><h4>{{seedSource==='excluded'?'已排除线索':'可用线索库'}} <span class="seed-count">{{(seedSource==='excluded'?(data?.seedTotal??0):(data?.allSeeds??data?.seeds.length??0)).toLocaleString()}}</span></h4><span class="muted">按来源筛选，搜索全部已提取线索</span></header><div class="seed-search-controls"><label class="seed-search"><Search :size="15"/><input v-model="seedSearch" placeholder="搜索域名、CNAME 或证书指纹" @input="searchSeeds"/></label><select v-model="seedSource" aria-label="线索来源分类" @change="searchSeeds"><option value="all">全部来源</option><option value="certificate">证书与 CT</option><option value="cname">CNAME</option><option value="host">已收录主机</option><option value="page">页面与脚本</option><option value="excluded">已排除线索</option></select></div><DiscoveryExclusions :project-id="projectId" :suggested-domain="seedSearch" @changed="refreshProgress(generation,true);queueLocal();emit('changed')"/><div class="seed-scroll" :aria-busy="reading"><table v-if="data?.seeds.length"><thead><tr><th>线索</th><th>发现依据</th><th>使用状态</th><th></th></tr></thead><tbody><tr v-for="seed in data.seeds" :key="seed.id"><td><code>{{seed.wildcard?'*.':''}}{{seed.host}}</code></td><td><span>{{sources[seed.source]||seed.source}}</span><small :title="seed.reference">{{seed.reference}}</small></td><td><span class="seed-state" :class="{'seed-eligible':seed.eligible||seed.queryEligible}">{{seed.excluded?'已排除 · 不参与补查':seed.wildcard?'通配符范围，非已发现主机':seed.eligible?'已在确认范围内':seed.queryEligible?'可精确关联，归属待核验':'外部线索，待确认'}}</span></td><td><button class="button ghost compact" :disabled="busy||seed.excluded||!(seed.eligible||seed.queryEligible)||seed.wildcard" @click="selectSeed(seed)">选择</button></td></tr></tbody></table><p v-else class="discovery-empty">{{reading?'正在读取线索…':seedSearch||seedSource!=='all'?'没有匹配的线索，请调整搜索或分类。':'尚无线索，先一键提取全部本地资产。'}}</p></div><footer class="seed-pagination"><span>匹配 {{(data?.seedTotal??data?.seeds.length??0).toLocaleString()}} 条 · 第 {{data?.seedPage??seedPage}} / {{pageCount}} 页</span><div><button class="button ghost compact" :disabled="reading||seedPage<=1" aria-label="上一页线索" @click="changePage(seedPage-1)"><ChevronLeft :size="15"/></button><button class="button ghost compact" :disabled="reading||seedPage>=pageCount" aria-label="下一页线索" @click="changePage(seedPage+1)"><ChevronRight :size="15"/></button></div></footer></section>
<details v-if="data?.requests?.length" class="query-explanation"><summary>历史 Hunter 请求回执</summary><pre>{{JSON.stringify(data.requests,null,2)}}</pre></details>
</template>
</section>
</template>
